                     margen: Math.round(m.contrib), riesgo: Math.round(m.risk), control: Math.round(m.control) };
        }

        calculateResults(state) {
            var ds = state.domainState;
            var period = state.currentPeriod;
            var out = { period: period };
            var i, j;
            var KP = ['precio', 'lineal', 'pares', 'ventas', 'margen', 'riesgo', 'control'];
            for (j = 0; j < KP.length; j++) { ds[KP[j] + 'History'] = []; }
            var rs = null;
            for (i = 1; i <= period; i++) {
                var r = this._roundScore(state, i);
                var kp = this._kpis(r.m);
                for (j = 0; j < KP.length; j++) { ds[KP[j] + 'History'][i - 1] = kp[KP[j]]; }
                ds.roundScores[i - 1] = r.score;
                ds.scoreHistory[i - 1] = r.score;
                rs = r;
            }
            ds.hardFail = rs.m.hard;
            var q = period - 1;
            ds.last = { roundScore: rs.score, hard: rs.m.hard };
            for (j = 0; j < KP.length; j++) { ds.last[KP[j]] = ds[KP[j] + 'History'][q]; }
            var score = this._composite(state);
            ds.performance = { overallScore: score };
            out.overallScore = score;
            out.score = score;
            out.roundScore = rs.score;
            for (j = 0; j < KP.length; j++) { out[KP[j]] = ds.last[KP[j]]; }
            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _event(dec, k) {
            var c = this.C;
            var self = this;
            var a = {};
            var j;
            for (j = 0; j < this.KEYS.length; j++) { a[this.KEYS[j]] = this._active(dec, k, this.KEYS[j]); }
            var pa = this.PAIS[a.pais1], pr = this.PROD[a.producto1], mo = this.MODO[a.modo2], ic = this.INCO[a.incoterm2];
            var pc = this.PREC[a.precio3], co = this.COBRO[a.cobro3], fa = this.FACT[a.factura4], aj = this.AJ[a.ajuste4];
            var dmk = (a.modo2 === 'distribuidor') ? c.DMK : 1.0;
            var chain = (1.0 + pa[4]) * dmk * c.RET * (1.0 + pa[2]);
            var pesc = this._clamp(pa[1] / chain - pa[5], c.P_MIN, c.P_MAX);
            var price = (pc[0] === 0.0) ? pc[1] : this._clamp(pesc * pc[0], c.P_MIN, c.P_MAX);
            var shelf = (price + pa[5]) * chain;
            var rel = shelf / pa[1];
            var pf = this._clamp(Math.pow(rel, -((rel > 1.0) ? c.EPS_UP : c.EPS_DN)), c.PF_MIN, c.PF_MAX);
            var distf = this._clamp(1.0 - mo[4] * pa[3] * (0.3 + pr[0]), 0.2, 1.0);
            var base = pa[0] * mo[0] * distf * pr[3] * pf * ic[0] * co[0] * fa[0];
            var sh = c.SEC_SHARE;
            var p1 = base * (1.0 - sh);
            var p2 = base * sh * aj[0];
            var pairs = p1 + p2;
            var netp = price * mo[1];
            var ucost = c.UC + pr[1];
            var revenue = p1 * netp + p2 * netp * aj[1];
            var vcost = pairs * ucost;
            var fixed = pr[2] + mo[2] * (1.0 - aj[3] * sh) + ic[1] + aj[2];
            var docs = fa[1] + fa[2] * pairs;
            var cover = revenue * co[3];
            var bad = revenue * co[1] * pa[7] * mo[5] * (1.0 - co[2]);
            var fx = revenue * pa[6];
            var tax = revenue * c.VAT_ES * (fa[3] + ((pa[8] === 1) ? ic[2] : 0.0));
            var contrib = revenue - vcost - fixed - docs - cover - bad - fx;
            var stress = revenue * co[1] * (1.0 - co[2]) * mo[5] * c.STRESS;
            var risk = stress + revenue * pa[9] + tax + mo[6] + aj[4];
            var hard = 0;
            this.HARD.forEach(function(h2) { if (a[h2[0]] === h2[1] && self.ROUND_OF[h2[0]] <= k) { hard += 1; } });
            return { k: k, a: a, price: price, shelf: shelf, pf: pf, pairs: pairs, revenue: revenue, contrib: contrib, risk: risk,
                     control: mo[3], invest: fixed + docs + cover, hard: hard };
        }

        _components(m) {
            var c = this.C;
            return [this._clamp((m.revenue - c.S_LO) / (c.S_HI - c.S_LO), 0, 1),
                    this._clamp((m.contrib - c.M_LO) / (c.M_HI - c.M_LO), 0, 1),
                    this._clamp((c.R_HI - m.risk) / (c.R_HI - c.R_LO), 0, 1),
                    this._clamp((m.control - c.K_LO) / (c.K_HI - c.K_LO), 0, 1)];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_S, c.W_M, c.W_R, c.W_K];
            var tw = 0, num = 0, i;
            for (i = 0; i < 4; i++) { tw += w[i]; num = num + w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.ROUND_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _r2(x) {
            return this._jsround(x * 100.0) / 100.0;
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'en') ? ',' : '.';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec2(n) {
            var v = Math.round(Math.abs(n) * 100);
            var whole = Math.floor(v / 100);
            var cents = v - whole * 100;
            var cs = (cents < 10 ? '0' : '') + String(cents);
            return (n < 0 && v > 0 ? '-' : '') + this._fmtInt(whole) + ((this._lang() === 'en') ? '.' : ',') + cs;
        }

        _fmtMoney(n) {
            var v = Math.round(n);
            var body = this._fmtInt(Math.abs(v));
            if (this._lang() === 'en') { return (v < 0 ? '-' : '') + '€' + body; }
            return (v < 0 ? '-' : '') + body + ' €';
        }

        _fmtMoney2(n) {
            var body = this._fmtDec2(Math.abs(n));
            if (this._lang() === 'en') { return (n < 0 ? '-' : '') + '€' + body; }
            return (n < 0 ? '-' : '') + body + ' €';
        }

        _fmtPct0(n) {
            return String(Math.round(n)) + ((this._lang() === 'en') ? '%' : ' %');
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var vH = ds.ventasHistory || [];
            var mH = ds.margenHistory || [];
            var rH = ds.riesgoHistory || [];
            var n = vH.length;
            this._set('ventasDisplay', n ? this._fmtMoney(vH[n - 1]) : '-');
            this._set('margenDisplay', n ? this._fmtMoney(mH[n - 1]) : '-');
            this._set('riesgoDisplay', n ? this._fmtMoney(rH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            if (!this.OPTS[g] || this.OPTS[g].indexOf(v) < 0) { return 'fb_next'; }
            var key = 'fb_' + this.PFX[g] + '_' + v;
            return this.FBKEYS[key] ? key : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._event(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

