            return {
                ventasChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Projected export sales', data: [], borderColor: '#7a3b1f', backgroundColor: 'rgba(122,59,31,0.12)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true }
                },
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Round score', data: [], borderColor: '#7a3b1f', backgroundColor: 'rgba(122,59,31,0.35)', borderWidth: 1 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var ventasHistory = ds.ventasHistory || [];
            var scoreHistory = ds.scoreHistory || [];
            var self = this;
            return {
                ventasChart: {
                    labels: ventasHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); }),
