                    ]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            var money = function(v) { return self._fmtMoney(v); };
            var money2 = function(v) { return self._fmtMoney2(v); };
            var pct0 = function(v) { return self._fmtPct0(v); };
            var int0 = function(v) { return self._fmtInt(v); };
            return [
                { key: 'results.precio', label: 'Export price (€/pair)', i18nKey: 'col_precio', formatter: money2 },
                { key: 'results.lineal', label: 'Shelf price (€)', i18nKey: 'col_lineal', formatter: money2 },
                { key: 'results.pares', label: 'Pairs sold', i18nKey: 'col_pares', formatter: int0 },
                { key: 'results.ventas', label: 'Export sales (€)', i18nKey: 'col_ventas', formatter: money },
                { key: 'results.margen', label: 'Contribution margin (€)', i18nKey: 'col_margen', formatter: money },
                { key: 'results.riesgo', label: 'Risk taken on (€)', i18nKey: 'col_riesgo', formatter: money },
                { key: 'results.control', label: 'Channel control (%)', i18nKey: 'col_control', formatter: pct0 },
                { key: 'results.roundScore', label: 'Round score', i18nKey: 'col_score' }
            ];
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var d = this._flat(state, mm);
            var m = this._event(d, mm);
            var kp = this._kpis(m);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
            if (m.hard > 0) { insights.push(this._t('cm_cap')); }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                precio: kp.precio,
                lineal: kp.lineal,
                pares: kp.pares,
                ventas: kp.ventas,
                margen: kp.margen,
                riesgo: kp.riesgo,
                control: kp.control,
                hard: m.hard,
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
