            return '<div class="ej2726-cm">'
                + '<div class="ej2726-cm-score">' + score + '<span class="ej2726-cm-max">/100</span></div>'
                + '<div class="ej2726-cm-verdict">' + (s.performanceLabel || '') + '</div>'
                + '<div class="ej2726-cm-kpis">'
