                + '<div class="ej2726-cm-kpi">' + this._t('cm_kpi_margen') + ' <strong>' + this._fmtMoney(s.margen || 0) + '</strong></div>'
                + '<div class="ej2726-cm-kpi">' + this._t('cm_kpi_riesgo') + ' <strong>' + this._fmtMoney(s.riesgo || 0) + '</strong></div>'
                + '<div class="ej2726-cm-kpi">' + this._t('cm_kpi_pares') + ' <strong>' + this._fmtInt(s.pares || 0) + '</strong></div>'
                + '<div class="ej2726-cm-kpi">' + this._t('cm_kpi_lineal') + ' <strong>' + this._fmtMoney2(s.lineal || 0) + '</strong></div>'
                + '<div class="ej2726-cm-kpi">' + this._t('cm_kpi_control') + ' <strong>' + this._fmtPct0(s.control || 0) + '</strong></div>'
                + '</div>'
                + '<div class="ej2726-cm-debrief">' + this._t('cm_debrief') + '</div>'
